bool
queue_t::healthy_live_v1 () const
{
  process_t &owner = process ();
  if (!owner.take_queue_health_query ())
    return false;

  try
    {
      if (owner.from_core () || !owner.os_driver ().is_debug_enabled ()
          || !is_valid () || m_os_queue_info.queue_type != os_queue_type_t::compute_aql)
        {
          owner.taint_queue_health ();
          return false;
        }

      os_queue_snapshot_entry_t current{};
      size_t count = 0;
      amd_dbgapi_status_t status = owner.os_driver ().queue_health_snapshot_v1 (
        &current, &count);
      if (status != AMD_DBGAPI_STATUS_SUCCESS || count != 1
          || !detail::same_healthy_queue_v1 (
            m_os_queue_info, current, os_exception_mask_t::queue_new,
            os_exception_mask_t::none))
        {
          owner.taint_queue_health ();
          return false;
        }
      return true;
    }
  catch (...)
    {
      owner.taint_queue_health ();
      throw; // Preserve the original exception; never regain a read permit.
    }
}

case AMD_DBGAPI_QUEUE_INFO_STATE:
case AMD_DBGAPI_QUEUE_INFO_ERROR_REASON:
  {
    // Bad output arguments do not consume a driver observation.
    if (value == nullptr)
      throw api_error_t (AMD_DBGAPI_STATUS_ERROR_INVALID_ARGUMENT);
    if (value_size != sizeof (uint32_t))
      throw api_error_t (AMD_DBGAPI_STATUS_ERROR_INVALID_ARGUMENT_COMPATIBILITY);
    if (!healthy_live_v1 ())
      throw api_error_t (AMD_DBGAPI_STATUS_ERROR_NOT_IMPLEMENTED);
    // These are conclusions from the live positive proof, never fallback
    // constants for an unsupported/unknown/error observation.
    const uint32_t result
      = query == AMD_DBGAPI_QUEUE_INFO_STATE
          ? static_cast<uint32_t> (AMD_DBGAPI_QUEUE_STATE_VALID)
          : static_cast<uint32_t> (AMD_DBGAPI_EXCEPTION_NONE);
    utils::get_info (value_size, value, result);
    return;
  }

struct os_queue_snapshot_entry_t
{
  os_queue_id_t queue_id;
  os_queue_state_t state{};
  bool exception_status_complete{ false }; // Never assume unknown raw bits are clean.
  os_agent_id_t gpu_id;
  os_queue_type_t queue_type{ os_queue_type_t::unknown };
  os_exception_mask_t exception_status;
  amd_dbgapi_global_address_t ring_base_address;
  amd_dbgapi_size_t ring_size;
  amd_dbgapi_global_address_t write_pointer_address;
  amd_dbgapi_global_address_t read_pointer_address;
  amd_dbgapi_global_address_t ctx_save_restore_address;
  amd_dbgapi_size_t ctx_save_restore_area_size;
};

amd_dbgapi_status_t
kfd_driver_t::queue_health_snapshot_v1 (
  os_queue_snapshot_entry_t *snapshot, size_t *queue_count) const
{
  if (snapshot == nullptr || queue_count == nullptr)
    return AMD_DBGAPI_STATUS_ERROR_INVALID_ARGUMENT;
  if (!is_valid () || !is_debug_enabled () || !m_os_pid || *m_os_pid <= 0
      || !s_kfd_fd)
    return AMD_DBGAPI_STATUS_ERROR_NOT_IMPLEMENTED;

  // Capacity one, no clearing, no heap or TRACE formatting. The caller has
  // already consumed its one baseline or one of ten lifetime query permits.
  const uint32_t pid = static_cast<uint32_t> (*m_os_pid);
  kfd_queue_snapshot_entry raw{};
  kfd_ioctl_dbg_trap_args args{};
  args.pid = pid;
  args.op = KFD_IOC_DBG_TRAP_GET_QUEUE_SNAPSHOT;
  args.queue_snapshot.exception_mask = 0;
  args.queue_snapshot.snapshot_buf_ptr = reinterpret_cast<uintptr_t> (&raw);
  args.queue_snapshot.num_queues = 1;
  args.queue_snapshot.entry_size = sizeof (raw);

  // Do not use kfd_ioctl(): it retries EINTR. This private observation gets
  // exactly one syscall, and every nonzero return is a refusal.
  const int result = ::ioctl (*s_kfd_fd, AMDKFD_IOC_DBG_TRAP, &args);
  if (result != 0)
    return result < 0 && errno == ESRCH
             ? AMD_DBGAPI_STATUS_ERROR_PROCESS_EXITED
             : AMD_DBGAPI_STATUS_ERROR;

  if (args.pid != pid
      || args.op != KFD_IOC_DBG_TRAP_GET_QUEUE_SNAPSHOT
      || args.queue_snapshot.exception_mask != 0
      || args.queue_snapshot.snapshot_buf_ptr
           != reinterpret_cast<uintptr_t> (&raw)
      || args.queue_snapshot.entry_size != sizeof (raw)
      || args.queue_snapshot.num_queues > 1)
    return AMD_DBGAPI_STATUS_ERROR;

  if (args.queue_snapshot.num_queues == 0)
    {
      *queue_count = 0; // A real empty snapshot, never a synthesized healthy row.
      return AMD_DBGAPI_STATUS_SUCCESS;
    }

  // Refuse all unknown as well as known exception bits before any mapping can
  // discard them. No queue flags, unsupported type or reserved ABI data qualify.
  if (raw.exception_status != 0 || raw.reserved != 0
      || (raw.queue_id
          & (uint32_t (KFD_DBG_QUEUE_ERROR_MASK)
             | uint32_t (KFD_DBG_QUEUE_INVALID_MASK))) != 0
      || raw.queue_type != KFD_IOC_QUEUE_TYPE_COMPUTE_AQL)
    return AMD_DBGAPI_STATUS_ERROR_NOT_IMPLEMENTED;

  os_queue_snapshot_entry_t observed{};
  observed.queue_id = raw.queue_id;
  observed.state = {};
  observed.exception_status_complete = true;
  observed.gpu_id = raw.gpu_id;
  observed.queue_type = os_queue_type_t::compute_aql;
  observed.exception_status = os_exception_mask_t::none;
  observed.ring_base_address = raw.ring_base_address;
  observed.ring_size = raw.ring_size;
  observed.write_pointer_address = raw.write_pointer_address;
  observed.read_pointer_address = raw.read_pointer_address;
  observed.ctx_save_restore_address = raw.ctx_save_restore_address;
  observed.ctx_save_restore_area_size = raw.ctx_save_restore_area_size;
  *snapshot = observed;
  *queue_count = 1;
  return AMD_DBGAPI_STATUS_SUCCESS;
}

virtual amd_dbgapi_status_t
queue_health_snapshot_v1 (os_queue_snapshot_entry_t *, size_t *) const
{
  return AMD_DBGAPI_STATUS_ERROR_NOT_IMPLEMENTED;
}

struct os_queue_snapshot_entry_t
{
  os_queue_id_t queue_id;
  os_queue_state_t state{};
  bool exception_status_complete{ false }; // Never assume unknown raw bits are clean.
  os_agent_id_t gpu_id;
  os_queue_type_t queue_type{ os_queue_type_t::unknown };
  os_exception_mask_t exception_status;
  amd_dbgapi_global_address_t ring_base_address;
  amd_dbgapi_size_t ring_size;
  amd_dbgapi_global_address_t write_pointer_address;
  amd_dbgapi_global_address_t read_pointer_address;
  amd_dbgapi_global_address_t ctx_save_restore_address;
  amd_dbgapi_size_t ctx_save_restore_area_size;
};

enum class os_runtime_state_t : uint32_t
{
  disabled = 0,
  enabled = 1,
  enabled_busy = 2,
  enabled_error = 3,
};

struct os_runtime_info_t
{
  amd_dbgapi_global_address_t r_debug;
  os_runtime_state_t runtime_state;
  bool ttmp_setup;
};

constexpr auto
ec_mask (os_exception_code_t c)
{
  using underlying_t = typename std::underlying_type_t<os_exception_code_t>;
  return 1ull << (static_cast<underlying_t> (c) - 1);
}

// Lose the positive proof before any callback/subscription/lifecycle effect.
if (runtime_info.runtime_state != os_runtime_state_t::enabled
    || m_queue_health.candidate ())
  m_queue_health.taint ();

auto restriction_error = utils::make_scope_exit (
  [this] ()
  {
    m_queue_health.taint ();
    os_driver ().set_exceptions_reported (
      os_exception_mask_t::process_runtime);
    m_runtime_state = AMD_DBGAPI_RUNTIME_STATE_LOADED_ERROR_RESTRICTION;
  });

// Qualify once, after continuous exception subscriptions were installed and
// before the runtime enable event is ACKed. Attached-existing and core paths
// cannot acquire this positive proof. A second lifetime cannot reset taint.
if (!is_flag_set (flag_t::runtime_enable_during_attach)
    && m_queue_health.begin_baseline ())
  {
    os_queue_snapshot_entry_t observed{};
    size_t observed_count = 0;
    const auto observed_status = os_driver ().queue_health_snapshot_v1 (
      &observed, &observed_count);
    m_queue_health.finish_baseline (
      observed_status == AMD_DBGAPI_STATUS_SUCCESS && observed_count == 0
      && os_driver ().is_debug_enabled ());
  }
else
  m_queue_health.taint ();

if (status != AMD_DBGAPI_STATUS_SUCCESS
    && status != AMD_DBGAPI_STATUS_ERROR_PROCESS_EXITED)
  fatal_error ("os_driver_t::query_debug_event failed (%s)",
               to_cstring (status));

// The driver returned the exact mask that was observed before clearing.
// A trap is not called benign: subscribed wave exceptions cannot reach
// the runtime without send_exceptions(), which taints before forwarding.
if (status != AMD_DBGAPI_STATUS_SUCCESS
    || (exceptions & ~(os_exception_mask_t::queue_wave_trap
                       | os_exception_mask_t::queue_new
                       | os_exception_mask_t::process_runtime))
         != os_exception_mask_t::none)
  m_queue_health.taint ();

if (status == AMD_DBGAPI_STATUS_ERROR_PROCESS_EXITED
    || exceptions == os_exception_mask_t::none)

// Sticky BEFORE any effect: failure/throwing handoffs cannot retry health.
if ((exceptions & ~os_exception_mask_t::process_runtime)
    != os_exception_mask_t::none)
  m_queue_health.taint ();
